"use client";

import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

interface AuthButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    isLoading?: boolean;
    children: React.ReactNode;
}

export function AuthButton({ isLoading, children, className, disabled, ...props }: AuthButtonProps) {
    return (
        <button
            disabled={disabled || isLoading}
            className={cn(
                "relative w-full bg-white text-black py-4 rounded-xl",
                "text-[12px] font-bold tracking-[0.15em] uppercase",
                "transition-all duration-200 ease-out",
                "hover:bg-white/90 hover:shadow-[0_0_20px_rgba(255,255,255,0.15)]",
                "active:scale-[0.98] active:shadow-none",
                "disabled:opacity-60 disabled:cursor-not-allowed disabled:active:scale-100",
                "focus:outline-none focus-visible:ring-2 focus-visible:ring-white/30 focus-visible:ring-offset-2 focus-visible:ring-offset-black",
                className
            )}
            {...props}
        >
            <span className={cn(
                "flex items-center justify-center gap-2 transition-opacity duration-150",
                isLoading && "opacity-0"
            )}>
                {children}
            </span>

            {/* Loading Spinner */}
            {isLoading && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="absolute inset-0 flex items-center justify-center"
                >
                    <svg 
                        className="animate-spin h-5 w-5 text-black" 
                        xmlns="http://www.w3.org/2000/svg" 
                        fill="none" 
                        viewBox="0 0 24 24"
                    >
                        <circle 
                            className="opacity-25" 
                            cx="12" 
                            cy="12" 
                            r="10" 
                            stroke="currentColor" 
                            strokeWidth="4"
                        />
                        <path 
                            className="opacity-75" 
                            fill="currentColor" 
                            d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                        />
                    </svg>
                </motion.div>
            )}
        </button>
    );
}
